CREATE TABLE `GPCL_MIG_VRF_TARGET` (
  `TABLE_ID` varchar(30) NOT NULL COMMENT '테이블ID (PK1)',
  `COL_ID` varchar(128) NOT NULL COMMENT '컬럼ID (PK2)',
  `COL_ORD` decimal(5,0) NOT NULL COMMENT '컬럼순번',
  `TABLE_NM` varchar(100) NOT NULL COMMENT '테이블명',
  `COL_NM` varchar(128) NOT NULL COMMENT '컬럼명',
  `DATA_TYPE` varchar(30) NOT NULL COMMENT '데이터타입',
  `PK_YN` char(1) NOT NULL DEFAULT 'N' COMMENT 'PK여부',
  `NULL_YN` char(1) NOT NULL DEFAULT 'N' COMMENT 'NULL여부',
  `SUM_YN` char(1) NOT NULL DEFAULT 'N' COMMENT '합계검증여부',
  `MIN_YN` char(1) NOT NULL DEFAULT 'N' COMMENT '최소검증여부',
  `MAX_YN` char(1) NOT NULL DEFAULT 'N' COMMENT '최대검증여부',
  `AVG_YN` char(1) NOT NULL DEFAULT 'N' COMMENT '평균검증여부',
  `HASH_YN` char(1) NOT NULL DEFAULT 'N' COMMENT '행값체크섬 검증여부. 네이티브 LOAD 는 적재측 해시 산출 불가라 N',
  `BYTE_LEN_YN` char(1) NOT NULL DEFAULT 'N' COMMENT '바이트길이합계 검증여부',
  `DIST_CNT_YN` char(1) NOT NULL DEFAULT 'N' COMMENT '고유값수 검증여부. COUNT(DISTINCT) 라 비용이 크므로 기본 N',
  `NULL_CNT_YN` char(1) NOT NULL DEFAULT 'N' COMMENT 'NULL건수 검증여부. C-b 포맷의 NULL 표기 결함을 잡는 안전망',
  `REG_ID` varchar(20) NOT NULL COMMENT '등록자',
  `REG_DTM` datetime NOT NULL DEFAULT current_timestamp() COMMENT '등록일시',
  `LST_ADJPRN_ID` varchar(20) NOT NULL COMMENT '최종수정자',
  `LST_ADJ_DTM` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '최종수정일시',
  PRIMARY KEY (`TABLE_ID`,`COL_ID`),
  KEY `IX_GPCL_MIG_VRF_TARGET_01` (`TABLE_ID`,`COL_ORD`),
  KEY `IX_GPCL_MIG_VRF_TARGET_02` (`TABLE_NM`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='검증 대상 - 컬럼별 합계·최소·최대·평균 검증 지정 여부. MIG-02에서 지정';

